try:
    risky_operation()
except Exception:
    print("Caught general exception")
except ValueError:  # This is unreachable because Exception catches everything
    print("This will never execute")

try:
    x = 5 + 10  # Simple arithmetic cannot raise FileNotFoundError
except FileNotFoundError:
    print("This will never execute")

try:
    process_data()
except BaseException:
    print("Caught base exception")
except Exception:  # Unreachable - BaseException catches all exceptions
    print("This will never execute")

compliant.code:
try:
    result = int(user_input)
except ValueError:
    print("Invalid number format")
except TypeError:
    print("Input is not a string")

try:
    risky_operation()
except ValueError:
    print("Value error occurred")
except Exception:
    print("Other exception occurred")

try:
    with open(filename, 'r') as f:
        content = f.read()
except FileNotFoundError:
